if (isStepPMOpening) {
	var pvcId = Number(api.getValue("PrevMaintConfig"));
	var dueExecEndDate = api.getValue("DueExecEndDate");
	if (!Ext.isEmpty(pvcId) && !Ext.isEmpty(dueExecEndDate)) {
		api.getFunctionOutputs("utils_prevmaintconfig_info_from_id_get", Ext.JSON.encode({
			pm_config_id: pvcId,
			reference_ts: dueExecEndDate
		})).then(function(output) {
			api.record.set("OpeningDate", (isActionPMOpeningAdvance ? new Date() : output[0].opening_date));
			api.record.set("ExpExecStartDate", output[0].exp_exec_start_date);
		});
	} else {
		api.record.set("OpeningDate", null);
		api.record.set("ExpExecStartDate", null);
	}
}

